let lang = 'zh'; // 目前介面語言

const CATEGORY_LABEL_ZH = {
  'Frozen Beverages':'冷凍飲品/果汁',
  'Gelato':'義式冰淇淋',
  'Other Beverages/ Ingredients':'其他飲品/原料',
  'Tea':'茶葉',
  'Toppings':'配料',
  'Packaging':'包材',
  '未分類':'未分類'
};
const CATEGORY_LABEL_EN = {
  'Frozen Beverages':'Frozen Beverages',
  'Gelato':'Gelato',
  'Other Beverages/ Ingredients':'Other Beverages/Ingredients',
  'Tea':'Tea',
  'Toppings':'Toppings',
  'Packaging':'Packaging',
  '未分類':'Uncategorized'
};
const CATEGORY_LABEL = CATEGORY_LABEL_ZH; // kept for any leftover direct references

function catLabel(cat){
  const map = lang === 'en' ? CATEGORY_LABEL_EN : CATEGORY_LABEL_ZH;
  return map[cat] || cat;
}
// 匯出檔案專用:不管目前 App 介面語言是什麼,分類一律用英文表示
function catLabelEN(cat){
  return CATEGORY_LABEL_EN[cat] || cat;
}

