function t(key){
  return (I18N[lang] && I18N[lang][key]) || I18N.zh[key] || key;
}

function tn(key, n){
  return t(key).replace('{n}', n);
}

// 支援多個具名參數的翻譯替換,例如 tf('partyProductPanelDesc', {name: party.name})
function tf(key, params){
  let s = t(key);
  Object.keys(params || {}).forEach(k => { s = s.split('{' + k + '}').join(params[k]); });
  return s;
}

async function setLang(newLang){
  lang = newLang;
  try{ localStorage.setItem('inventoryAppLang', lang); } catch(e){}
  try{ await dbSet('lang', lang); } catch(e){}
  applyStaticTranslations();
  updateImportCountDisplay();
  renderCurrentUserBadge();
  updateAppHeaderTitle();
  renderTabBar();
  renderAll();
  const fm = document.getElementById('forecastMsg'); if(fm){ fm.textContent = ''; fm.className = 'msg'; } // 舊語言的提示訊息清掉
  setTxType(currentTxType);
}

function toggleLang(){
  setLang(lang === 'zh' ? 'en' : 'zh');
}

// 「顯示隱藏商品」勾選狀態存進這台裝置的 localStorage,重新整理頁面後才會記得(見 boot() 裡的還原邏輯)。
function toggleShowHiddenProducts(checked){
  try{ localStorage.setItem('showHiddenProductsPref', checked ? 'true' : 'false'); } catch(e){}
  renderStockCards();
}

function applyStaticTranslations(){
  document.querySelectorAll('[data-i18n]').forEach(el => {
    // 標題旁的 ⓘ 說明按鈕(nav.js initTitleHints 加進去的)不能被 textContent 洗掉,先拿下來、寫完文字再放回去
    const hintBtn = el.querySelector(':scope > .title-hint-btn');
    el.textContent = t(el.getAttribute('data-i18n'));
    if(hintBtn) el.appendChild(hintBtn);
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    el.innerHTML = t(el.getAttribute('data-i18n-html'));
  });
  document.querySelectorAll('optgroup[data-i18n-label]').forEach(el => { el.label = t(el.getAttribute('data-i18n-label')); });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
  });
  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    el.title = t(el.getAttribute('data-i18n-title'));
  });
  document.getElementById('langToggleBtn').textContent = t('langToggle');
}
